    const used = new Set(sleepers.filter((b) => b !== a).map((b) => b.bedSlot));
    for (let i = 0; i < BED_SLOTS.length; i++) if (!used.has(i)) return [i, SPOT.bed[0] + BED_SLOTS[i][0], SPOT.bed[1] + BED_SLOTS[i][1]];
    return [-1, a.x, a.z];
