      if (!q) {
        p.view.play("dance");
        p.busy = 2.4;
        continue;
      }
      p.view.yaw = Math.atan2(q.x - p.x, q.z - p.z);
      p.view.play(Math.random() < 0.5 ? "happy" : "dance");
      p.busy = 2.4;
      p.mode = "idle";
